    """Current tenant-visible representation of one v2 computer.  Durable metadata is read from PostgreSQL. `state` is observed on the runtime-owning node when the computer is active, so this response never exposes the internal `remote` routing sentinel as a lifecycle state."""
    computer_id: str
    created_at: str
    #: Whether inactivity-based automatic sleep is disabled.
    keep_alive: bool
    #: Allocated memory in MiB, from the durable computer record.
    mem_size_mib: int
    owner_id: str
    state: VmState
    #: Allocated vCPUs, from the durable computer record.
    vcpu_count: int
    #: Private guest-network address assigned to this computer.
    ip: Optional[str] = None
    labels: Optional[dict[str, str]] = None
    #: Checkpoint this computer was restored from, if any.
    parent_checkpoint_id: Optional[str] = None
    #: Owning project. `None` identifies an Uncategorized computer.
    project_id: Optional[str] = None

