    RUNNING = "running"
    PAUSED = "paused"
    SLEEPING = "sleeping"
    RECOVERY_REQUIRED = "recovery_required"
    DEAD = "dead"
    DELETING = "deleting"
    DELETED = "deleted"
    REMOTE = "remote"
    INDETERMINATE = "indeterminate"
    TEMPORARILY_UNAVAILABLE = "temporarily_unavailable"

